&lt;style&gt;
/* 🔹 Contenedor principal */

.c-generic35951{
 background-color: #1b6ab2;
}

.vip-carousel-container {
 text-align: center;
 padding: 2rem 1rem;
 background: #1b6ab2;
 color: #fff;
 font-family: Arial, sans-serif;
}

/* Título */
.vip-carousel-title {
 margin-bottom: 1.5rem;
 font-size: 1.8rem;
 font-weight: bold;
 color: #fff;
}

/* Envoltorio */
.vip-carousel-wrapper {
 position: relative;
 max-width: 1200px;
 margin: auto;
 /* Eliminamos overflow hidden aquí para permitir ver flechas fuera si se desea, 
 pero mantenemos la ventana controlada */
}

/* Ventana */
.vip-carousel-window {
 overflow: hidden;
 width: 100%;
}

/* Track */
.vip-carousel-track {
 display: flex;
 transition: transform 0.5s ease;
 width: 100%;
}

/* 
 ESTRATEGIA EXPERTA:
 El &lt;a&gt; (.vip-card) define el ancho exacto (20%, 33%, etc).
 El padding crea el espacio visual entre tarjetas.
 El .vip-card-inner maneja el borde redondeado y la imagen.
*/
.vip-card {
 flex: 0 0 20%; /* 5 items por defecto */
 max-width: 20%; /* Asegura que no crezca más */
 padding: 0 8px; /* ESTO REEMPLAZA AL MARGIN: Crea el espacio */
 box-sizing: border-box; /* Crucial para que el padding no rompa el ancho */
 text-decoration: none;
 display: block;
}

/* Contenedor interno para dar estilo (bordes, fondo) */
.vip-card-inner {
 border-radius: 12px;
 overflow: hidden;
 transition: transform 0.3s ease;
 background: #1b6ab2; /* Fondo por si la imagen no carga */
}

.vip-card img {
 width: 100%;
 height: auto;
 display: block;
}

/* Hover effect limpio */
.vip-card:hover .vip-card-inner {
 transform: scale(1.05);
 box-shadow: 0 10px 20px rgba(0,0,0,0.3);
}

/* Botones de navegación */
.vip-carousel-btn {
 position: absolute;
 top: 50%;
 transform: translateY(-50%);
 background: rgba(0,0,0,0.6);
 border: none;
 color: #fff;
 font-size: 2rem;
 cursor: pointer;
 padding: 0;
 width: 40px;
 height: 40px;
 border-radius: 50%;
 transition: background 0.3s ease;
 z-index: 10;
 display: flex;
 align-items: center;
 justify-content: center;
 line-height: 1;
}

.vip-carousel-btn:hover {
 background: rgba(0,0,0,0.9);
}

.vip-prev { left: 0px; }
.vip-next { right: 0px; }


/* 🔹 Responsive - Cambiamos solo el porcentaje de flex */
@media (max-width: 1024px) {
 .vip-card { flex: 0 0 33.333%; max-width: 33.333%; } /* 3 visibles */
}

@media (max-width: 768px) {
 .vip-card { flex: 0 0 50%; max-width: 50%; } /* 2 visibles */
}

@media (max-width: 480px) {
 .vip-card { flex: 0 0 100%; max-width: 100%; padding: 0 20px; } /* 1 visible */
}
&lt;/style&gt;


&lt;script&gt;
const vipTrack = document.querySelector(&#039;.vip-carousel-track&#039;);
const vipCards = document.querySelectorAll(&#039;.vip-card&#039;);
const vipPrev = document.querySelector(&#039;.vip-prev&#039;);
const vipNext = document.querySelector(&#039;.vip-next&#039;);

let vipIndex = 0;

// 1. Determinar cuántas tarjetas se ven según CSS
function getVisibleItems() {
 if (window.innerWidth &lt;= 480) return 1;
 if (window.innerWidth &lt;= 768) return 2;
 if (window.innerWidth &lt;= 1024) return 3;
 return 5; // Desktop
}

function updateVipCarousel() {
 const visibleItems = getVisibleItems();
 // MAGIA MATEMÁTICA: Movemos por porcentaje, no por píxeles.
 // Si se ven 5, cada una ocupa 20%. Si el index es 1, movemos 20%.
 const percentageToMove = 100 / visibleItems;
 
 vipTrack.style.transform = `translateX(-${vipIndex * percentageToMove}%)`;
}

// Botón Siguiente
vipNext.addEventListener(&#039;click&#039;, () =&gt; {
 const visibleItems = getVisibleItems();
 const maxIndex = vipCards.length - visibleItems; // Límite para no pasar al vacío
 
